<script setup lang="ts">
import { AlertTriangle, ArrowDownRight, ArrowUpRight, Boxes, CircleDollarSign, ClipboardList, RefreshCw, Users } from '@lucide/vue';
const config = useRuntimeConfig();
const route = useRoute();
const { token } = useWorkspaceSession();
const data = ref<any>(null);
const loading = ref(false);
const error = ref('');
const props = defineProps<{ pageSection?: string }>();
const section = computed(() => props.pageSection || String(route.query.section || 'overview'));
const titles: Record<string,{eyebrow:string;title:string;description:string}> = {
  overview: { eyebrow:'КОМПАНИЯ / 30 ДНЕЙ', title:'Пульс бизнеса', description:'Ключевые результаты и точки внимания по всей экосистеме' },
  sales: { eyebrow:'ФИНАНСОВЫЙ СРЕЗ', title:'Продажи и каналы', description:'Оборот, количество заказов и вклад каждого канала' },
  customers: { eyebrow:'КЛИЕНТСКАЯ АНАЛИТИКА', title:'Клиенты и развитие', description:'Рост клиентской базы, CRM-нагрузка и качество сервиса' },
};
const title = computed(() => titles[section.value] || titles.overview);
const money = (value: number) => Number(value || 0).toLocaleString('ru-RU', { maximumFractionDigits: 0 });
const channelLabels: Record<string,string> = { WEB:'Интернет-магазин',B2B:'B2B',WILDBERRIES:'Wildberries',OZON:'Ozon',YANDEX_MARKET:'Яндекс Маркет',MEGAMARKET:'Мегамаркет',MANUAL:'Ручной заказ',ONE_C:'1С' };
const salesChannels = computed(() => data.value?.channels || []);
const maxChannelRevenue = computed(() => Math.max(1, ...salesChannels.value.map((item:any) => Number(item.revenue || 0))));
async function load() { loading.value = true; error.value = ''; try { data.value = await $fetch('/leadership/overview', { baseURL: config.public.apiBase, headers: { Authorization: `Bearer ${token.value}` } }); } catch (e:any) { error.value = e?.data?.message || 'Не удалось загрузить управленческие показатели'; } finally { loading.value = false; } }
onMounted(load);
</script>

